/* Landfall — the key crew's own page (Lachlan, 2026-11-18; DESIGN.md "Twelve key crew", "The officer's page").
   Tap an officer on the People view and this is what opens: who they are when nothing is wrong (nature), how they are
   now, how they see the colony, how they see you, and what they make of each of the others. Every line is theirs and is
   checked against their section of VOICES.md. LF.profile(s, p) is a pure function of the state: no dice, nothing stored,
   no numbers shown. Lines never name a count, a date or another officer outside "on", so they stay true in any game.
   No DOM. */
(function () {
'use strict';
/* now: fine, spent (sent in person and resting), frayed (nerve), failing (health), hurt (laid up).
   colony: good, steady, hungry, low (morale), dread (something is pressing), grim (what the colony has done).
   you: four bands of regard, best first (LF.standing). on: the ten who are not this seat's other officer. */
const P = {
  solheim: {
    now: { fine: `"I'm fit for duty and I've read this morning's reports, so unless you've brought me something that isn't in them, we're both wasting the light."`, spent: `"I'm off the roster until the doctor signs me back on, which doesn't stop me reading, so have the departments send their reports to my bunk and I'll mark them up from there."`, frayed: `"I'm sleeping about half what I should, and I've checked my own work against last season's to see whether it shows yet. It doesn't, so the subject is closed until it does."`, failing: `"It's a cough, and I've had it long enough to know what it costs me, so I've moved the heavy work to the mornings and nothing has slipped."`, hurt: `"I'm laid up, which is not the same as relieved, so the morning reports come to this bed at the usual hour and the orders go out from it."` },
    colony: { good: `"The colony is standing, fed and ahead of where I'd have put it, and that's exactly the moment people start calling it finished. It isn't, and I want foundations going in while we can afford them."`, steady: `"We're holding our ground, and I'll take that over losing it, but holding doesn't put up a single wall. I want to know what we're building next and who I'm pulling off what to do it."`, hungry: `"The stores don't cover the mouths, and no amount of looking at the figure is going to change it. Cut the ration now while it's still a decision, because if you wait it becomes something that happens to us."`, low: `"They're tired and they've stopped bothering to hide it from me, which tells me how far it's gone. Give them a piece of work with an end they can see, and let them finish it."`, dread: `"Something out there is costing us people at a rate I can put a figure on, and I can't yet put one on what it would cost to find it and stop it. I want that second figure before anyone else goes out."`, grim: `"We did what kept this colony alive, and I'd give the same orders again with the same information. I've got the count of what it cost, and I don't need anyone to read it back to me."` },
    you: [`"You decide quickly and you don't go back over it afterwards looking for someone to tell you it was right. That's rarer than it should be, and I can work with it."`, `"You give the orders and I carry them out, and when I think you're wrong I'll say so once, before the order and not after. That's the arrangement, and it's held so far."`, `"You hesitate, and you call it weighing things up. I've counted what the last delay cost us, and I'd rather you made a bad call on time than a good one late."`, `"I follow the office, because a colony that picks and chooses its orders doesn't last. Don't mistake that for following you."`],
    on: { dahl: `"Nolan starts from the position that everyone's guilty and works backwards, which saves him a great deal of time. He's right often enough that I've stopped asking him to justify it."`, kovacs: `"When Jeremy tells me how long a machine has left, I plan for exactly that long, because in all the years I've known him he hasn't once been wrong in my favour."`, nakamura: `"Andrea has ignored a direct order of mine before, and the patient lived, so I let it stand. She should understand that I was counting, and that she's had her one."`, yurbin: `"Mac is worth any three surveyors I've worked with, and sooner or later he'll get one of them killed finding out something we needed to know. I keep a list of where he's allowed to go, and I keep it short."`, estrada: `"Samuel does the work in front of him without being asked twice and without telling me how he feels about it. If I had ten of him I'd have the fields in a year."`, zulu: `"Toby won't spend his people, and one of these days the colony is going to need him to. I'd rather he learned how from me, in daylight, than from whatever's at the wire that night."`, halloran: `"Roberta gets a job done in half the time I gave her, and tells me afterwards what she took apart to do it. So far the arithmetic has come out in our favour, and I check it every time."`, brandt: `"Lou gives me the real figure the first time I ask, with no cushioning on it. He's the only doctor I've worked with who understood that I can't plan around a kindness."`, iyer: `"Michelle and I put the same price on things, and we both know it. The difference is that she says it out loud in front of people, and I've asked her to stop."`, waititi: `"Hamond promises people things at supper that I then have to find the materials for. I've spoken to him about it twice, and I fully expect to do it a third time."` } },
  dahl: {
    now: { fine: `"I'm fine, which is to say nothing's tried to kill me since breakfast, and I've learned not to read much into that."`, spent: `"I'm resting, apparently, so if the wire falls over this month you'll know it wasn't my fault, and I'll be sure to remind you."`, frayed: `"I check the locks twice a night. Lately it's three times, and before you say anything, the third time I found one open."`, failing: `"I'm told I look like death, which is bloody rich coming from this place, where the competition's so stiff."`, hurt: `"I'm flat on my back with a hole in me, and the worst of it is I can hear the watch enjoying themselves."` },
    colony: { good: `"Everyone's fed and smiling, and I've never trusted a full room, because full rooms are where people start wondering what else they're owed."`, steady: `"It's quiet, and I'd like to tell you quiet means safe, but in my experience quiet means somebody's thinking."`, hungry: `"The stores are short, so now we find out who everyone really is, and I can save you the suspense, because I've got a list."`, low: `"They've stopped complaining to my face, and that's the bit that worries me, because people who've stopped complaining have started planning."`, dread: `"I said this place wanted us dead and I was told I was being dramatic, and I notice nobody's saying that now."`, grim: `"We've done things I'd have arrested a man for on the docks, and I helped, so don't look to me for a clean conscience, I've only the one and it's in use."` },
    you: [`"You've not lied to me yet, that I've caught, and from me that's very nearly affection."`, `"I'll follow your orders, and I'll keep my own notes on them, and we'll both hope nobody ever needs to read the notes."`, `"You want to be liked, and I understand it, but it's a bloody expensive habit in somebody who holds the keys."`, `"I've stopped arguing with you, and if you knew me better you'd find that a good deal more worrying than the arguing."`],
    on: { solheim: `"Jane would trade any one of us for the colony and not lose a night over it, and I sleep better knowing somebody would."`, kovacs: `"Jeremy's the only man here who's never once tried to charm me, and I can't tell you how restful that is."`, nakamura: `"Andrea would give the last blanket to the man who stole the others, and then she'd ask me why I've got him in a cell."`, yurbin: `"Mac would open the gate to anything that knocked, provided it knocked in an interesting way."`, estrada: `"Samuel's honest, as far as I can tell, and I've looked, because an honest man with the keys to the seed store is either a saint or very patient."`,
      achebe: `"Lucas believes people, all of them, the first time, and I'd find it sweet if I weren't the one who has to clear up after."`, halloran: `"Roberta's taken something out of the lander that I'm fairly sure was holding the rest of it together, and she called me 'sunshine' when I asked."`, brandt: `"Lou sees through people the way I do, only he says it to their faces, and I'd call it brave if I thought he'd noticed it was dangerous."`, iyer: `"The professor's got a locked cabinet and a very calm manner, and I've never met that pair of things together and been glad of it."`, waititi: `"Hamond knows everything that happens here before I do and tells it to whoever's peeling next to him, so he's either my best source or my worst leak."` } },
  kovacs: {
    now: { fine: `"I'm upright and nothing's on fire, which around here counts as a good morning, so ask me again once something's broken and I'll have a proper answer for you."`, spent: `"I'm meant to be resting, and I am resting, but I can hear that pump from my bunk and I don't like the note it's making, so somebody had better go and look at it before I do."`, frayed: `"I lie awake going through everything that's due to fail and what order it'll go in, and I know that's not sleep, but at least by morning I've got a list."`, failing: `"I run rough in the mornings these days and it takes me a while to settle, same as everything else that came off that ship, so give me an hour before you ask me for anything clever."`, hurt: `"I'll mend, I've mended from worse, but keep everybody off my bench while I'm laid up, because I know where every tool on it is and I won't when they've finished helping."` },
    colony: { good: `"Everything's running the way it should, and I don't trust that for a minute, because in my experience it only means something's wearing out in a place I haven't thought to look yet."`, steady: `"We're getting by on patches, and they're good patches because I put them on myself, but they're still patches, and I'd like someone to remember that the next time they ask me for more."`, hungry: `"I can't weld food, so whatever you're planning to do about the stores, do it before the crews are too weak to hold a spanner, because after that nothing I look after stays running."`, low: `"You can tell how people are by how they treat their tools, and right now half of them are being left out in the weather, so I'd say we're in worse shape than anyone's admitting."`, dread: `"I fix machines, and whatever that is out there isn't one, so I can't tell you how long it's got or what it'll do next, and I don't mind saying that bothers me more than the thing itself."`, grim: `"I kept my head down and my hands busy while all that was going on, and I told myself it wasn't my department. Doesn't mean I didn't see it, and I've not slept right since."` },
    you: [`"You let me finish one job before you hand me the next, and you don't stand over me while I do it. I've worked for a lot worse for a lot longer, and I'd tell anyone so."`, `"You ask for something, I fix it, and then you ask for something else, and so far you've listened when I've said how long it'd take. It's a living, and I've no complaints worth the breath."`, `"You keep spending what I've saved up, parts and hours and people, like there's more where it came from. There isn't, and I'd rather you heard that from me now than from a dead machine later."`, `"I'll keep everything running because there are people who'll die if I don't, and that's the whole of the reason. You're not in it, so you can stop coming down here to ask."`],
    on: { solheim: `"Jane always wants it done by a date, and I always tell her the real one instead, and to her credit it's the real one she writes down."`, dahl: `"Nolan goes round checking my locks after I've already checked them, and I used to take it personal, but these days I just let him, since it saves me the second walk."`, nakamura: `"Andrea'll come down here and shout at me about the clinic's kit like I broke it on purpose, and an hour later she's back with soup. I don't follow it, but I eat the soup."`, yurbin: `"Mac borrows my tools without asking and brings them back with something growing on them, and then he wants to tell me what it is, like that's meant to make up for it."`, estrada: `"Samuel and I can work a whole shift side by side and not say ten words between us, and I'd take that over most conversations I've ever had."`, achebe: `"Lucas asks me what I need and then he actually goes and gets it, with no speech attached. It took me a good long while to stop waiting for the catch."`, zulu: `"Toby takes the worst of the night watches himself so his lot can sleep, and nobody's told him yet that he can't keep that up. He reminds me of somebody stupid I used to be."`, brandt: `"Lou told me how long my knees have got left, flat out, same way I'd tell a man about a bearing. I didn't enjoy it, but I've trusted him since."`, iyer: `"The professor wants more power for her bench every month and won't tell me what it's for, so I've started saying no before she's finished asking, and I sleep fine."`, waititi: `"Hamond talks the entire time I'm working, about nothing at all, and I gave up asking him to stop a long time ago. He does always bring something to eat, I'll give him that."` } },
  nakamura: {
    now: { fine: `"I'm all right, and you don't have to ask me in that careful voice, because that's the one I use on patients and I know exactly what it means."`, spent: `"I've been told to rest, by me, and I'm discovering what my patients have always known, which is that I give very good advice and I'm impossible to take it from."`, frayed: `"I keep going back over the ones I lost, every night, and don't you tell me to stop. Tell me what you'd have done differently in my place, or leave me to it."`, failing: `"Yes, I know what it is, I've watched it in enough other people. And no, you're not taking me off the ward for it, because there's nobody behind me and you know that as well as I do."`, hurt: `"I'm a terrible patient, and I've been told so twice already today by people I trained. Somebody bring me the ward list, because I can read it perfectly well lying down."` },
    colony: { good: `"Look at them out there, fed and warm and arguing about nothing at all. That's what I came out here for, and I'd like you to stand here a minute and see it before you go back to your lists."`, steady: `"They're getting by, and I know that's supposed to be good news. I want better than getting by for these people, and so should you, and I'm going to keep saying so."`, hungry: `"I'm seeing it in the children first, the way you always do, in their wrists and in how quiet they've gone. Don't you wait for the ration count to tell you what I'm telling you now."`, low: `"Half of what walks into my ward these days isn't sickness at all. It's people who've stopped believing that any of this gets better, and I can't stitch that or dose it."`, dread: `"People are frightened and nobody's telling them the truth about why. Frightened people I can treat, but once they work out they've been lied to they stop coming in, and then I lose them."`, grim: `"I've put my name to things here that I'll answer for, and so will you. Don't you dare stand in my ward and tell me it was necessary, not where they can hear you."` },
    you: [`"You came down to the ward and looked at them before you decided, when you could have just sent for the figures. That's all I've ever asked of anyone in your chair, and you did it without being asked."`, `"We'll work together well enough. I'll tell you when you're wrong, loudly and in front of people, and some of those times you'll thank me for it later."`, `"You keep calling them hard choices, as if the hardness were yours. It's only ever hard for the people you didn't choose, and I'm the one who sits with them after."`, `"I'm staying for my patients, because they haven't done anything to deserve losing their doctor. I want you to know that's the only reason I'm still standing in this room."`],
    on: { solheim: `"Jane keeps a count of the dead so that she never has to know them, and I understand why she does it. I know every one of hers by name, and one day I'm going to say them to her."`, dahl: `"Nolan spends his life waiting for people to let him down, and I'd feel sorry for him if he didn't look quite so satisfied every time they do."`, kovacs: `"Jeremy takes my night shift when I'm dead on my feet and never says a word about it the next day. Don't you tell him I've noticed, because he'd stop."`, yurbin: `"Mac comes in with a new burn and a grin and a story about what did it. I stopped asking him to be careful a long time ago, and now I just keep the dressings where he can reach them."`, estrada: `"Samuel fasts when the stores are low and thinks I can't tell by looking at him. I can tell, and I put an extra ladle in his bowl, and neither of us mentions it."`, achebe: `"Lucas listens to me properly, all the way to the end, without once looking at the door. And then he asks me to be reasonable, and I could throttle him."`, zulu: `"Toby brings his people in himself, whatever the hour, and then waits outside until I've seen them. I've told him to go home to bed, and he says 'yes, doctor' and stays exactly where he is."`, halloran: `"Roberta swears like a docker, and I've watched her hold a frightened girl's hand right through a bone setting without letting go once. I like her enormously."`, iyer: `"Michelle calls my patients 'cases', in my ward, where they can hear her. I've asked her once not to, and she should know I don't ask twice."`, waititi: `"Hamond feeds everyone who looks sad, which out here is everyone, and half of them come out of his kitchen better than they come out of my ward. I've stopped being jealous and started sending them."` } },
  yurbin: {
    now: { fine: `"Good, I'm good, I'm, have you seen what's come up along the fence line? No, me, right, yes, fine, never better."`, spent: `"They've got me resting, which is, I mean it's fine, I've got my notes, I've got so many notes, could someone bring the other box?"`, frayed: `"I'm not sleeping, but it's not the bad kind, it's that every time I shut my eyes I think of another thing I should've measured."`, failing: `"It's interesting, actually, the cough, it's got a pattern to it, I've been timing it, don't make that face."`, hurt: `"Completely worth it, I got the sample, it's in the, where's my bag? Somebody's got my bag."` },
    colony: { good: `"We're fed, we're standing, so can we please, finally, go and look at the thing I keep asking about?"`, steady: `"It's all very sensible at the moment and I'm trying to be grateful and not bored."`, hungry: `"There's food out there, I'm nearly sure of it, look, give me a party and a month and I'll tell you what's safe to eat. Mostly safe."`, low: `"Everyone's so glum, and I do understand it, but we're standing on a world nobody's ever seen, and I can't make that stop being wonderful."`, dread: `"Yes it's frightening, of course it is, but it's also the first really new thing anyone's ever, sorry. Sorry. People have died. I do know that."`, grim: `"I've gone along with things. I told myself it was for the answer. I've stopped checking whether that's true."` },
    you: [`"You let me look. Nobody ever just lets me look. I'd follow you into, well, I'd follow you most places."`, `"You say no about half the time, which is, honestly, better than I'm used to."`, `"You keep choosing not to know things. I don't understand how you can stand it."`, `"I've stopped bringing you what I find. You'd only tell me to bury it."`],
    on: { solheim: `"Jane's got a list of places I'm allowed to go and it's so short, it's, I've seen longer lists on a jar."`, dahl: `"Nolan thinks everything out there wants to kill us, and fine, he's sometimes right, but he never once asks why it does."`, kovacs: `"Jeremy says I've ruined his good pliers. I haven't ruined them, they're colonised, it's completely different."`, nakamura: `"Andrea patches me up and doesn't lecture, or she does, but she's bandaging while she does it, so it counts as kind."`, estrada: `"Samuel talks to his plants and I talk to my jars and neither of us mentions it. It's a good arrangement."`,
      achebe: `"Lucas hears the whole idea out before he says no, which is, I think that's actually worse?"`, zulu: `"Toby insists on coming along to keep me alive, and he's so serious about it, I keep trying to show him things and he keeps looking the other way for trouble."`, halloran: `"Roberta built me a sample rig out of a kettle and something off the lander, in an afternoon, swearing the whole time. She's a marvel."`, brandt: `"Lou told me exactly what it would do to my lungs, in order, and I said that's fascinating, and he said that wasn't the response he was after."`, waititi: `"Hamond will eat anything I bring back if I say it's probably fine, which makes him the bravest man here or the, no, it's the other one."` } },
  estrada: {
    now: { fine: `"I'm well enough, thanks for asking. The ground's been kind to us this month, and when the ground's kind I don't find much to complain about."`, spent: `"They've told me to rest, so I'm sitting with the seedlings, which is about as much rest as I know how to take. They don't mind the company, and I don't mind the quiet."`, frayed: `"I've not been sleeping much, if I'm honest with you. I go out and sit in the rows when it gets bad, and that helps some, though I couldn't tell you why."`, failing: `"I'm slower than I was, and I won't pretend otherwise. The beds don't mind slow, though, so long as I get round to all of them, and so far I have."`, hurt: `"I'll be up again soon enough, so don't fuss. Somebody ought to water the near beds while I'm down, and tell them not too much, because they'll drown the roots trying to be kind."` },
    colony: { good: `"Folk are fed and nobody's going short, and I can't remember the last time I could say both of those together. I've said my thanks for it, and I'd say them again."`, steady: `"We're getting by, and I think getting by is worth more than people give it credit for. Build slow and eat steady, and we'll still be here when the fast ones aren't."`, hungry: `"The stores are thin, and there's no dressing that up. So we all eat thinner, every one of us together, and the old folks and the little ones are the last to feel it, or I'll want to know why."`, low: `"People are worn right down, and I don't blame them for it. One good harvest would mend more of that than any amount of talking, so I'm putting what I've got into the beds."`, dread: `"I don't know what it is out there, and I won't pretend I'm not afraid of it. I pray on it at night, and then in the morning I go and check the fences, because I figure both are owed."`, grim: `"We've done wrong here, and I was part of it, whatever I told myself at the time. I'm not asking to be let off. I'd only ask that we don't do it again."` },
    you: [`"You've been fair with the weak ones when it would've been easier not to be, and that's the thing I watch for in a person. I'm with you, and I'll say so to anyone who asks."`, `"You do your work and I'll do mine, and I don't see that there needs to be any hard words between us. If that changes, I'll come and tell you to your face."`, `"You've let some folks go short who couldn't stand to, and I've seen it happen more than the once. I haven't said much about it. I want you to know I've noticed all the same."`, `"I've worked beside you a long time and held my tongue through most of it, because I thought you'd come right. I don't think that now, and I'm done holding it."`],
    on: { solheim: `"Jane sees the whole colony at once, like a field from up on a hill, and she's good at it. I only wish she'd come down and look at it one face at a time, now and then."`, dahl: `"Nolan thinks the worst of everybody he meets, me included, I'd guess. I leave tomatoes on his step anyway, and I notice they're always gone by morning."`, kovacs: `"Jeremy and me can work a whole day through and not talk, and both go home feeling we had a fine conversation. He's a good man. He's tired, but he's good."`, nakamura: `"Andrea fights for every last one of them like they were her own. She slips extra in my bowl on fast days and thinks I haven't seen, and I let her think it."`, yurbin: `"Mac doesn't mean any harm to anybody. Harm just sort of follows him around, like a dog he never asked for, so I keep him out of the seed store."`, achebe: `"Lucas is a fair man. He asks you a thing and then he waits and listens to the answer, and I can't say that of many folks who've had the giving of orders."`, zulu: `"Toby looks after his people the way a shepherd would, counting them in every night. He's awful young to be carrying that many, and I pray for him by name."`, halloran: `"Roberta's got a mouth on her that'd curdle milk. She fixed my pump in one afternoon, though, and when I tried to thank her she told me where to put it, kindly."`, brandt: `"Lou says hard things to people, and I've never yet heard him say one that wasn't true. He sits up through the night with the dying, too. I've seen his lamp from the beds."`, iyer: `"The professor came and asked me which of the seed lines I could spare for her trials. I told her none of them, and she wrote that down, and I've kept the store locked since."` } },
  achebe: {
    now: { fine: `"I'm well, thanks, and I mean that as an answer and not a way of ending the conversation. How are you holding up? Sit down a minute, I'm asking properly."`, spent: `"I've been stood down for a while, and that's fair enough, because I'd order anybody else in my state to rest and I'd expect them to do it without an argument."`, frayed: `"I'm not at my best at the moment, and I'd rather you heard that from me than worked it out from watching. I'm still doing the job, and I'm trusting you to tell me if that stops being true."`, failing: `"The doctor's told me I need to slow down, and I'm taking it seriously. What I'm trying to work out is which part of all this is the part that can honestly wait, and I haven't found it yet."`, hurt: `"I'll be back on my feet before long. In the meantime every department knows what I need from it this month, and I trust them to get on with it without me standing over them."` },
    colony: { good: `"People are doing their jobs and looking out for each other without being told to, and that's as much as I've ever wanted from any crew. I keep wanting to ask for more, and I'm trying not to."`, steady: `"We're all right. We're not comfortable, and I wouldn't tell anyone we were, but I think everybody in this colony knows exactly where we stand, and that counts for a lot with me."`, hungry: `"We're short, and people know we're short, because I stood up at muster and gave them the real figure. They took it a good deal better than they'd have taken finding out I'd rounded it up."`, low: `"Morale's poor, and I've never once seen it fixed by telling people to cheer up. What they need is to watch one thing go right, start to finish, so let's pick something we can actually finish."`, dread: `"People are frightened, and they've every reason to be, so I won't insult them by saying otherwise. What I can give them is the truth as far as we know it, and something useful to do with their hands."`, grim: `"My test was always whether I could stand up at muster and say out loud what we'd done. There are things now that I couldn't, and I helped decide them, and I haven't worked out how to carry that."` },
    you: [`"You say what you're going to do and then you do it, and when it goes wrong you say so before anyone has to ask. That's all I've ever wanted from anybody, and I've rarely had it from the person above me."`, `"I think we work well enough together. I'd like to be told more, and told sooner, and I'm saying so now, plainly, so that it doesn't come as a surprise when I bring it up again."`, `"You've kept things from this colony that were theirs to know, and I've stood next to you in public while you did it. I'm telling you now that I won't keep doing that blind."`, `"I gave you a second chance, and I told you at the time exactly what that meant coming from me. I'm sorry it's come to this, and I mean that, but I did tell you."`],
    on: { dahl: `"Nolan's quite sure I'm naive, and he might even be right about that. I'd still rather be wrong my way now and then than be right his way every day of my life."`, kovacs: `"Jeremy tells me what he needs and how long it'll take him, and then that's precisely what happens. I've never had to chase him for anything, and I wish I had six more like him."`, nakamura: `"Andrea will fight me on just about anything, in front of whoever happens to be in the room, and she's usually got a point. I'd much sooner have that than someone who nods and then does nothing."`, yurbin: `"Mac's the cleverest person I've ever worked with, and I've had to tell him no more often than everyone else put together. He takes it very well, and then he asks again as if I'd never said it."`, estrada: `"Samuel's never missed a day's work or asked me for a single thing for himself. So on the rare occasions he comes to tell me I've got something wrong, I stop what I'm doing and listen."`, zulu: `"Toby takes every loss on himself, as though he'd personally let it happen. I've told him more than once that carrying those is my job and not his, and he says he understands, and he doesn't believe a word of it."`, halloran: `"Roberta tells me a month and has it done in half that, nine times out of ten, and I love her for it. I've learned to keep something in reserve for the tenth."`, brandt: `"Lou's rude to me and he's right, usually in the same sentence. I decided a long time ago that I can work with both, as long as he keeps being right."`, iyer: `"Michelle doesn't always tell me what she's started until it's well under way. We've had that conversation once, and she was very gracious about it, and I'd rather not need to have it a second time."`, waititi: `"Hamond promises people things I can't possibly give them, because he can't bear to see anyone disappointed. He always comes and owns up before I've had to ask, though, so he and I stay square."` } },
  zulu: {
    now: { fine: `"I'm fit for duty, thank you, and so is everyone on the watch. I walked the whole wire myself this morning and there's nothing I need to bring to you."`, spent: `"I've been taken off the rota until I'm cleared, and my second has the watch in the meantime. She's very good and I trust her with it, but I'd be lying if I said I didn't want to be out there."`, frayed: `"I haven't been sleeping well, and I've told my second so that at least one person on the watch knows to check my work. I thought you ought to know as well, since it's your colony I'm guarding."`, failing: `"I'm not as strong as I was, and I don't think that's going to change. I've rewritten the rota so that nobody on the wire is depending on me being fast, because that wouldn't be fair to them."`, hurt: `"I'll heal, it's nothing that won't mend. Before anything else, though, could you tell me whether everyone else got back inside the wire? Nobody will give me a straight answer."` },
    colony: { good: `"Everyone's inside the wire tonight and everyone's had a proper meal, and nobody on the watch has had to raise a weapon all month. I honestly don't need more than that to call it a good one."`, steady: `"It's holding. My people are tired and they could do with more hands, but every one of them is still here, and I count them every night, so I'd know."`, hungry: `"The watch is on exactly the same ration as everybody else, and I've made certain of that myself, because it has to be seen to be true. I'll admit that hungry people standing a wire at night worry me a great deal."`, low: `"People are getting short with each other over very small things. I've asked the watch to go gently and to walk people home rather than write them up, because most of the trouble I'm seeing now is only tiredness."`, dread: `"I can't protect them from something I can't see, and I've had to say that to my people's faces, which was the hardest thing I've done here. I'm doing everything I know how to do, and I know it isn't enough."`, grim: `"I've carried out orders here that I shouldn't have, and I want that understood. I did them with my own hands so that nobody on the watch would have to live with it, and that doesn't make any of them right."` },
    you: [`"In all this time you've never once asked me to throw away one of mine to make a point. I've noticed that, every time it could have gone the other way, and I wanted to thank you for it properly."`, `"I'll follow your orders, as I always have. All I'd ask is that you hear me out before you give them, because I'm the one who has to look my people in the eye afterwards."`, `"You sent my people out past the wire on a guess, and you called it a risk worth taking. I haven't forgotten who didn't come back, and I don't think I'm going to."`, `"I'll keep the wire, because the people inside it haven't done anything wrong and they still need keeping safe. I'd be grateful if you didn't ask me for anything beyond that."`],
    on: { solheim: `"The commander would send my people out past the wire if her figures told her to, and she'd be honest with me about why. I respect her a great deal, and I go over her figures myself before I sign anything."`, kovacs: `"Jeremy came and fixed the latch on the gate without anybody asking him to, and when I thanked him he said the noise had been annoying him. I think he was looking out for the watch and didn't want it mentioned."`, nakamura: `"Dr Tete has never turned one of mine away, at any hour of the night, and she's never once made them feel they were a bother. I owe her more than I know how to say to her."`, yurbin: `"Mac walks straight towards whatever it is, every time, and I walk next to him because somebody has to. One of these days I'm not going to be fast enough, and I think about that more than I should."`, estrada: `"Samuel brings hot food up to the night watch when it's cold and leaves it by the gate without a word. He doesn't make anything of it, so we don't either, but every one of my people knows who it's from."`, achebe: `"Lucas backs me when I make a call, in front of everyone, and he did it even the time my call turned out to be wrong. I haven't forgotten that, and I'd walk a long way for him because of it."`, halloran: `"Roberta calls me 'soldier boy' in front of the watch, and I've asked her politely not to. She also built them a stove for the gatehouse out of nothing, in her own time, so I've decided to let it go."`, brandt: `"Dr Chang told me that I couldn't go on taking every night watch myself, and he didn't soften it at all. He was right, and I've changed the rota, and I'll admit I didn't enjoy hearing it."`, iyer: `"The professor asked whether she could borrow two of the watch, and she wouldn't tell me what for. I said no as politely as I could, and I'll go on saying no for as long as she won't tell me."`, waititi: `"Hamond comes up to the wire some evenings and makes the watch laugh until they can hardly stand. They need that a good deal more than they'd ever admit to me, so I pretend not to hear."` } },
  halloran: {
    now: { fine: `"I'm fine, boss! Covered in shit to the elbows and I've not sat down since breakfast, but fuck it, that's a good day in my trade."`, spent: `"Rest, they said. Rest! I've been lying here going out of my bloody mind, boss. I rebuilt the kettle twice out of boredom, and it's a better fucking kettle now, so you're welcome."`, frayed: `"I'm fine. I'm FINE! Christ. I know I'm rattling on, I can hear it, but if I shut up I start thinking, and I'm not doing that, boss. Fuck that."`, failing: `"I'm knackered, boss, properly knackered, and it's not shifting. Hands still work, though! So don't you dare take me off the tools, because sitting about would finish me quicker than this shit will."`, hurt: `"Ah, it's nothing, I've had worse off a toaster! Just tell whoever's on my bench that if they move one piece of my shit I'll know, and I'll come down there on one leg and kick their arse."` },
    colony: { good: `"Everything works, boss! All of it! At the same fucking time! I don't know what to do with myself. I'm going to build something daft just because I can, and you never saw me."`, steady: `"It's holding, boss. Fuck knows how, half of it's wire and swearing, but it's holding. Just don't lean on anything, and for God's sake don't kick it."`, hungry: `"I can make a pump out of a kettle, boss, but I can't make dinner out of scrap! Believe me, I tried, and it was shit. Somebody feed my crew before one of them faints into a lathe."`, low: `"Everyone's got a face like a dropped pie and it's doing my fucking head in! I've tried jokes, I've tried shouting, I've tried taking the piss. Nothing! You can't fix that with a spanner, boss, and I hate it."`, dread: `"No. No jokes, boss, not about that. Whatever the fuck that thing is, I want a wall between it and us, a proper one, and I'll weld the bastard myself tonight if you give me the plate."`, grim: `"I built some of that shit, boss. I knew what it was for and I built it anyway. So no, I don't joke about it, and you don't get to either."` },
    you: [`"You let me have a go, boss! Even the stupid ideas! Half the bastards I've worked for would've written me up for asking. I'd wire a bomb for you, I swear to God. Don't ask me to."`, `"You're all right, boss. Bit too fucking fond of a schedule, and you pull that face when I say 'roughly', but you're all right."`, `"You want it faster, I give you faster, shit breaks, and then you look at me like I broke it! That's your maths, boss, not mine. I told you at the time, and I've got witnesses."`, `"I'll fix what's broken because people need it, and none of this is their fault. That's it. That's all you get. Stay the fuck out of my workshop."`],
    on: { solheim: `"Jane scares the shit out of me, boss, and I'd still follow her off a cliff! Mind you, she'd have checked the cliff first. Twice. With a clipboard."`, dahl: `"Nolan reckons I'm nicking parts off the lander. Of course I'm nicking parts off the lander! Where the fuck does he think his gate hinges came from, the hinge fairy?"`, nakamura: `"Andrea'd square up to God himself over a patient, and she'd bloody win. I'd be right behind her, holding her coat and shouting."`, yurbin: `"Mac wants a rig to hold something that, his words, boss, 'mostly stays put'. Mostly! Fucking hell. Yes, obviously I built it."`, estrada: `"Samuel doesn't swear, doesn't shout, doesn't drink. What the fuck do I do with that? Lovely man. Absolutely no idea what to say to him."`, achebe: `"Lucas doesn't shout at you. He does this face, boss, this sad disappointed face, like you've pissed on his birthday cake. I'd pay good money to be shouted at."`, zulu: `"Toby's gone out past the wire himself again, the daft bastard! He's got a whole watch! Will somebody tell him he's allowed to send one of them?"`, brandt: `"Lou's ruder than me, boss, and he does it without one single swear word. Not one! How? It's fucking unnatural. I've been taking notes."`, iyer: `"Michelle asked me, dead polite, for a lock that only opens from the outside. From the outside, boss! I said I was busy. I'm going to stay busy till one of us dies."`, waititi: `"Me and Hamond have a still behind the seed store. You didn't hear that from me! You'll hear it from him by supper, the man can't keep his mouth shut to save his life."` } },
  brandt: {
    now: { fine: `"I'm adequate, which at my age and in this place is a better result than I'd have predicted. I'd tell you if it were otherwise, since unlike most of my patients I don't see the point in lying to the doctor."`, spent: `"I've prescribed myself rest, and I'm finding out that I'm a poor patient with an even worse doctor. He keeps telling me to lie down, and I keep finding reasons why his opinion doesn't apply to me."`, frayed: `"I'm tired in the particular way that sleep doesn't fix, and I know the clinical name for it, having written it on other people's charts for thirty years. It turns out that knowing the name is no help whatever."`, failing: `"I know precisely how ill I am, and roughly how long it will take, and I'd rather not go over it with an amateur. When there's something you need to plan around, I'll tell you, and I'll tell you in time."`, hurt: `"I'm laid up, as you can see. I'm told the clinic is managing perfectly well without me, and I notice that nobody who says so is willing to tell me how."` },
    colony: { good: `"People are well, and it's making them believe that it will last, which is the one symptom of good health I've never been able to treat. Don't correct them yet. Let them have the month."`, steady: `"Nobody's dying this month who shouldn't be, and you'd be surprised how seldom I've been able to say that. Out here I'd call it a good result and try not to look at it too closely."`, hungry: `"I can give you a list tonight of who the short ration will kill first, in order, with a fair guess at when. You won't want to read it, and that's exactly why you ought to have it on your desk."`, low: `"It isn't illness, though they come to me as if it were. They've stopped expecting anything good to happen, and I've nothing on the shelf for that, so I listen to them, which is slower and works about as well."`, dread: `"At the moment the fear is doing more damage than whatever it is they're afraid of, and I see it in the ward every morning. I'd like that to remain true, and I've no confidence at all that it will."`, grim: `"I wrote in the record that I advised against it, and then I did it properly, because doing it badly would have been worse. I've gone back and read that page since, and I can tell you it's no comfort."` },
    you: [`"You ask me the real question, the one you'd rather not hear the answer to, and then you sit there and listen to it. You'd be astonished how few people in your position ever manage both halves."`, `"You'll do. I've worked under a good many who were worse, and I told each of them so at the time, so you can take it that I'd have mentioned it by now."`, `"You've got into the habit of coming to me after you've already decided, hoping I'll give you a medical reason to feel better about it. I don't keep those in stock, and I'd stop asking."`, `"I treat everyone who comes through that door, whoever they are and whatever they've done, and that includes you. I'd advise you not to read anything more into it than that."`],
    on: { solheim: `"Jane wants a figure from me and nothing else, and I give her the figure, and she thanks me and leaves. We've never needed to like each other, which I find saves us both a great deal of time."`, dahl: `"Nolan likes to think of himself as a cynic. He gets up in the night to check the locks so that nobody else in this colony has to lie awake afraid, and I'm sorry to tell him that's not what cynics do."`, kovacs: `"Jeremy's knees are finished, and he asked me straight out, so I told him straight out. He nodded and went back to work, and I've had a good deal of respect for him ever since."`, yurbin: `"Mac is going to die of something he found interesting, probably with his notebook open. I've explained this to him, and he's thought it over and decided that it's a fair price, and I can't honestly fault his arithmetic."`, estrada: `"Samuel fasts at times when his body can't afford it, and I've told him so in the plainest terms I have. He thanked me very sincerely, and he's carried on exactly as before."`, achebe: `"Lucas trusts everyone until they prove him wrong, and it costs him something every single time it happens. What interests me is that he knows this perfectly well and keeps paying anyway."`, zulu: `"Toby hasn't slept properly in longer than he'd admit. If you ask him he'll tell you he's fine, and he'll say it in a complete sentence with his back straight, which is how you can tell that he isn't."`, halloran: `"Roberta makes more jokes the worse things get, so I've learned to read her the way I'd read a fever chart. I should tell you that lately she's been very funny indeed."`, iyer: `"Michelle is the cleverest person in this colony and she has no brakes of any kind. I said as much to her face, and she agreed with the first half and asked me to define the second."`, waititi: `"Hamond talks about his wife as though she were in the next room, when she's asleep in a cradle in orbit and may well stay there. I haven't had the heart to say so to him, which I assure you is unusual for me."` } },
  iyer: {
    now: { fine: `"I'm perfectly well, thank you, Administrator, and the work is proceeding about as I expected it to. If either of those things changes, you'll have it from me before you hear it from anyone else."`, spent: `"I've been asked to rest, and I've complied in the sense that I haven't left my quarters. I'm using the time to write up, which I'd argue breaks no instruction and wastes considerably less of the month."`, frayed: `"I'm sleeping rather less than I ought to, and I'm aware of it. I've been checking my own error rate against last season's as a precaution, and so far the work hasn't suffered, so I don't propose to change anything."`, failing: `"My health is declining at a rate I'm able to estimate fairly well. I've put my notes in an order that a competent successor could follow, because it would be a waste for the work to stop merely because I had."`, hurt: `"It's an injury, and it's an inconvenience, and I expect to be back at the bench shortly. In the meantime I'd be grateful if you'd see to it personally that nothing there is moved or cleaned."` },
    colony: { good: `"Conditions are about as favourable as they're likely to get, which means that for once we have capacity to spare. I'd strongly suggest spending it on finding things out, Administrator, while the finding out is still cheap."`, steady: `"The colony is stable, and I recognise that most people find that reassuring. A stable system tells you very little about itself, however, so I'd like your permission to push on one or two things and see what gives."`, hungry: `"The shortage is a matter of simple arithmetic. There are things growing within sight of the wire that we've never tested on a person, and with a few volunteers I could tell you by next month which of them are food."`, low: `"Morale isn't my field, and I won't pretend to expertise I haven't got. I would only observe that people who've been given a result to look forward to work measurably better than people who haven't, and I could supply one."`, dread: `"It's the most important thing we've found since we landed, and I understand perfectly well that it's also killing people. I'd put it to you that those are both reasons to study it, and neither is a reason to look away."`, grim: `"We paid a price for what we now know, and I've never pretended otherwise or asked anyone else to. The only version of this I'd regret is the one where we paid the same price and learned nothing from it."` },
    you: [`"You allow the work to proceed, and you actually read what comes of it before you form a view. I've no complaint to make, Administrator, and I'd ask you to appreciate how seldom I've been able to say that."`, `"I think we understand each other well enough. You refuse roughly half of what I ask for, and since you're consistent about which half, I've been able to plan around it."`, `"You keep choosing not to know things that we could know by the end of the season. I've recorded each refusal with its date, so that when one of them turns out to have mattered we'll be clear about when we could have found out."`, `"I've stopped asking for your permission, Administrator, since the answer had become predictable. I thought on balance that you'd prefer to be told that than to discover it."`],
    on: { solheim: `"The commander and I arrive at the same cost for most things, by much the same reasoning. She'd prefer that I didn't say it aloud in front of the others, and I've never understood what keeping quiet is supposed to change."`, dahl: `"Mr Edney has someone watch my bench, and I think he's quite right to. I'd only mention, since it's of no use to him now, that he's been watching the wrong door."`, kovacs: `"The mechanic refuses me any additional power as a matter of principle, without asking what I'd do with it. I consider it a poor principle, though I'll grant that he applies it very consistently."`, nakamura: `"Dr Tete believes that whichever patient is in front of her is the whole of the question. It's an admirable way to practise medicine, and I'm afraid it stops working at about the size of this colony."`, estrada: `"Mr Barlow declined to lend me any of his seed stock for the trials, and he was extremely polite about it. I expect he'll be every bit as polite on the day it turns out he was wrong."`, achebe: `"Lucas asked me to tell him before I begin anything new, and I thought that was a reasonable request, so I agreed to tell him. You'll notice that I was careful not to say when."`, zulu: `"Mr O'Neal won't lend me two of his watch, because he's convinced that I'd lose them. I told him I'd lose one at the very most, and for some reason that didn't seem to help."`, halloran: `"Roberta will build whatever I ask for inside a day, and she doesn't think to ask what it's for until after it's finished and working. That's very nearly my idea of the perfect colleague."`, brandt: `"Dr Chang is of the opinion that I've no brakes, and he's said so to my face, which I respect. He's mistaken, as it happens. I simply don't apply them in the places where he would."`, waititi: `"Mr Shepherd has offered, more than once, to taste things for me. He's the only volunteer I've ever had to turn away for too much enthusiasm, since I'd learn nothing from a man who'll eat anything."` } },
  waititi: {
    now: { fine: `"Me? Never better! Well, no, that's a lie, I've often been better, I was better at my cousin's wedding. But I've eaten, the soup was hot and nobody's shouted at me yet today, so I'm calling it a win."`, spent: `"I'm resting, on doctor's orders, and it's absolute torture, because nobody ever comes to visit a man who's resting. So sit down. No, sit! I want to hear everything, start with whoever's fallen out with whoever."`, frayed: `"I'm not sleeping, if you want the truth, and I've run out of people who'll talk to me at that hour of the night. So I've been going out and talking to the beans, and I'll say this for them, they're very polite about it."`, failing: `"I've lost weight. Me! Look at this belt, I've had to make a new hole in it. Now don't you go telling Dalia when she comes down, because she'll only say she liked the old one better, and she'd be right."`, hurt: `"The doctor tells me it'll only hurt when I laugh. So naturally I've been in agony since breakfast, and it's my own fault, I can't seem to stop myself."` },
    colony: { good: `"Will you look at that hall! Full plates and loud tables and somebody singing badly at the back. I could cry, and I have done, a bit, behind the pots. Don't tell anyone, I've got a reputation to keep up."`, steady: `"We're all right, you know. The soup's on the thin side but it's hot and there's enough of it to go round, and I've not heard a single complaint, and believe me, I hear every one there is."`, hungry: `"I'm not making any jokes about this one, so don't wait for it. There isn't enough to go round. And I can tell you exactly who's been giving their share away under the table, because somebody needs to stop them, and it ought to be you."`, low: `"Nobody laughs at supper any more, and I've tried all my best ones, even the one about the goat. I'll tell you something for nothing: when I can't get a laugh out of a room, that room's in real trouble."`, dread: `"Everyone's whispering about it, and sooner or later they all come and whisper it to me, every word, and I wish to God they wouldn't. I lie awake after with all of it going round, and I've nobody to pass it on to."`, grim: `"I fed people while it was being done, and I stood there and told jokes while it was being done, so they'd eat. I've been turning it over ever since, and I honestly couldn't tell you what that makes me."` },
    you: [`"You've kept the children's table full through all of it, even when it cost you somewhere else, and for that I'd walk into the sea for you. I'd complain the whole way down the beach, mind, but I'd go."`, `"You're all right, you know that? You should come and eat with us more often and not at your desk. People like to see the one in charge chew, it settles them, I can't explain it."`, `"They talk to me about you, you know, when they're peeling. I've been sticking up for you, because I think you mean well, but I'll be honest with you, it's getting to be hard work."`, `"I've tried to find a way to make a joke out of what you did, because that's how I get past things. I've tried and tried, and I can't do it, and that's the worst thing I know how to say about anybody."`],
    on: { solheim: `"Jane has never once laughed at a single thing I've said, not in all these years. I've made it my life's work, and I'm telling you, one day I'll get her, and I want witnesses."`, dahl: `"Nolan's got it into his head that I'm a leak. Well, of course I'm a leak, I've never denied it! But I leak to him as much as to anyone, so I don't see what he's got to moan about."`, kovacs: `"Jeremy lets me sit and talk at him for hours while he works, and he never says a word back, not one. He's the best listener in the whole colony, and I don't think he knows he's doing it."`, nakamura: `"Andrea sends me the sad ones to feed, the ones she can't find anything wrong with. Between her ward and my kitchen I reckon we've got a whole clinic going, and mine smells better."`, yurbin: `"Mac brings me things from outside the wire to taste, because he knows I'll try anything once. I've only been properly ill off it the twice, which I think is a very good record, considering."`, achebe: `"Lucas gives me this sad, disappointed look whenever I've promised somebody too much, like a dog you've forgotten to walk. I swear I'd sooner he just hit me with a shovel and had done with it."`, zulu: `"Toby's far too young to look as tired as that. I send a pot of soup up to the wire every night, and he thinks it's for the watch, bless him. It's for him. The watch can have what's left."`, halloran: `"Roberta and I have got a little still going. Now, I wasn't supposed to tell you that, and I wasn't supposed to tell anyone, and somehow the whole colony knows. I can't think how."`, brandt: `"Lou's the rudest man I've ever had the pleasure of feeding, and I'll tell you this, he's never once left a crumb on the plate. He was kind to me about Dalia one night, too. Don't you dare tell him I said so."`, iyer: `"The professor frightens me, and I'm not a man who frightens. She asked me what I'd be willing to eat for her, and like a fool I said anything. I've been wishing I hadn't ever since."` } },
};
LF.PROFILE = P;
/* What is said of one who is gone, in the plain voice of the file. */
const goneLine = o => o.left ? `${o.first} is gone from the colony.` : `${o.first} is dead.`;
const nowKey = (s, p) => LF.laidUp && LF.laidUp(s, p) ? 'hurt' : p.body < 40 ? 'failing' : p.mind < 45 ? 'frayed' : p.spent && p.spent > s.day ? 'spent' : 'fine';
const colonyKey = s => { const lean = LF.lean && LF.lean(s), heat = LF.heat ? LF.heat(s) : 0, grim = LF.hum ? LF.hum(s) < 25 : false;
  return s.res.food <= 0 || lean ? 'hungry' : heat >= 2 ? 'dread' : grim ? 'grim' : s.morale < 30 ? 'low' : s.morale >= 62 && !heat ? 'good' : 'steady'; };
const youKey = p => (p.loyal >= 75 ? 0 : p.loyal >= 45 ? 1 : p.loyal >= 25 ? 2 : 3);
/* The page. null for anyone who is not one of the twelve (a colonist promoted in an old save, a notable). */
LF.profile = function (s, p) {
  const D = p && p.key && P[p.key]; if (!D) return null;
  const f = LF.FILE[p.key] || {}, yrs = Math.floor((s.day || 0) / LF.YEAR);
  const where = p.orbit ? `Aboard the ${s.world ? s.world.ship : LF.SHIP}, keeping the ship.` : p.away ? 'Out past the wire with a party.' : '';
  const others = [];
  for (const seat of LF.SEAT_ORDER) { if (seat === p.seat) continue;
    const o = LF.officer(s, seat), g = !o && LF.lastHeld ? LF.lastHeld(s, seat) : null, q = o || g;
    if (!q || !q.key || !D.on[q.key]) continue;
    others.push({ id: q.id, key: q.key, name: q.name, first: q.first, seat: LF.SEATS[seat].name, seatKey: seat, gone: !o, line: o ? D.on[q.key] : goneLine(q) }); }
  return { key: p.key, name: p.name, title: LF.title(p), seat: LF.SEATS[p.seat].name, age: f.age ? f.age + yrs : null, from: f.from || '', record: f.record || [],
    normal: p.nature || '', where, nowKey: nowKey(s, p), now: p.orbit ? '' : D.now[nowKey(s, p)], colonyKey: colonyKey(s), colony: D.colony[colonyKey(s)],
    youKey: youKey(p), you: D.you[youKey(p)], standing: LF.standing ? `${p.first} ${LF.standing(p)}.` : '',
    sore: p.sore && p.loyal < 45 && s.day - p.sore.d < 240 ? p.sore.t : '', bonds: LF.bondLine ? LF.bondLine(s, p) : '', others };
};
})();
